CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL, email VARCHAR(120) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL);
CREATE TABLE libraries (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, owner_id INT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (owner_id) REFERENCES users(id));
CREATE TABLE library_members (library_id INT NOT NULL, user_id INT NOT NULL, role ENUM('owner','editor','viewer') NOT NULL, PRIMARY KEY(library_id,user_id), FOREIGN KEY (library_id) REFERENCES libraries(id) ON DELETE CASCADE, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE saved_pages (id INT AUTO_INCREMENT PRIMARY KEY, library_id INT NOT NULL, source_url TEXT NOT NULL, created_by INT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (library_id) REFERENCES libraries(id) ON DELETE CASCADE, FOREIGN KEY (created_by) REFERENCES users(id));
CREATE TABLE snapshots (id INT AUTO_INCREMENT PRIMARY KEY, saved_page_id INT NOT NULL, version_no INT NOT NULL, title VARCHAR(500) NOT NULL, clean_html MEDIUMTEXT NOT NULL, plain_text MEDIUMTEXT NOT NULL, fetched_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, http_status SMALLINT NOT NULL, UNIQUE(saved_page_id,version_no), FOREIGN KEY (saved_page_id) REFERENCES saved_pages(id) ON DELETE CASCADE, FULLTEXT(title, plain_text));
CREATE TABLE assets (id INT AUTO_INCREMENT PRIMARY KEY, snapshot_id INT NOT NULL, source_url TEXT NOT NULL, local_name VARCHAR(255) NOT NULL, mime VARCHAR(100) NOT NULL, FOREIGN KEY (snapshot_id) REFERENCES snapshots(id) ON DELETE CASCADE);
CREATE TABLE tags (id INT AUTO_INCREMENT PRIMARY KEY, library_id INT NOT NULL, name VARCHAR(60) NOT NULL, UNIQUE(library_id,name), FOREIGN KEY (library_id) REFERENCES libraries(id) ON DELETE CASCADE);
CREATE TABLE saved_page_tags (saved_page_id INT NOT NULL, tag_id INT NOT NULL, PRIMARY KEY(saved_page_id,tag_id), FOREIGN KEY(saved_page_id) REFERENCES saved_pages(id) ON DELETE CASCADE, FOREIGN KEY(tag_id) REFERENCES tags(id) ON DELETE CASCADE);
CREATE TABLE notes (id INT AUTO_INCREMENT PRIMARY KEY, snapshot_id INT NOT NULL, user_id INT NOT NULL, body TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(snapshot_id) REFERENCES snapshots(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
